function(node){
  var hasFill = (node.fills||[]).some(function(f){return f.type==='SOLID';});
  var hasStroke = (node.strokes||[]).length > 0;
  if (!hasFill && !hasStroke) return null;
  if (!node.cornerRadius || node.cornerRadius < 4) return null;
  if (!node.height || node.height < 24 || node.height > 72) return null;
  if (!node.width || node.width < 48 || node.width > 360) return null;
  var texts = node.textChildren || [];
  if (texts.length < 1) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  var conf = 80;
  if (node.height >= 28 && node.height <= 56) conf += 5;
  if (node.width >= 60 && node.width <= 300) conf += 5;
  return { confidence: Math.min(conf, 92), reason: '有背景色+圆角+文字，符合按钮特征（高度'+Math.round(node.height)+'px，宽度'+Math.round(node.width)+'px）' };
}

function(node){
  var hasFill = (node.fills||[]).some(function(f){return f.type==='SOLID';});
  if (!hasFill) return null;
  if (!node.cornerRadius || node.cornerRadius < 8) return null;
  if (!node.width || !node.height) return null;
  if (node.width > 140 || node.height > 40) return null;
  if (node.width < 20 || node.height < 14) return null;
  var texts = node.textChildren || [];
  if (texts.length < 1) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  var isCapsuled = node.cornerRadius >= node.height / 2 - 2;
  var conf = isCapsuled ? 85 : 75;
  return { confidence: conf, reason: '胶囊形小标签（'+Math.round(node.width)+'×'+Math.round(node.height)+'，圆角'+node.cornerRadius+'）' };
}

function(node){
  if (!node.width || node.width < 300) return null;
  if (!node.height || node.height < 32 || node.height > 60) return null;
  if (node.layoutMode !== 'HORIZONTAL') return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  var childCount = node.childCount || 0;
  if (childCount < 2) return null;
  return { confidence: 78, reason: '横排筛选栏（宽'+Math.round(node.width)+'px，'+childCount+'个子元素）' };
}

function(node){
  if (!node.width || node.width < 300) return null;
