function(node){
  if (!node.width || !node.height) return null;
  if (node.width < 36 || node.width > 68) return null;
  if (node.height < 18 || node.height > 36) return null;
  if (!node.cornerRadius || node.cornerRadius < node.height/2 - 3) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  var hasFill = (node.fills||[]).some(function(f){return f.type==='SOLID';});
  if (!hasFill) return null;
  var childCount = node.childCount || 0;
  if (childCount < 1) return null;
  return { confidence: 85, reason: '胶囊形开关（'+Math.round(node.width)+'×'+Math.round(node.height)+'px）' };
