function(node){
  if (!node.width || !node.height) return null;
  if (node.width < 14 || node.width > 28) return null;
  if (node.height < 14 || node.height > 28) return null;
  var diff = Math.abs(node.width - node.height);
  if (diff > 4) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  var hasStroke = (node.strokes||[]).length > 0;
  var hasFill = (node.fills||[]).some(function(f){return f.type==='SOLID';});
  if (!hasStroke && !hasFill) return null;
  return { confidence: 75, reason: '正方形/圆形小控件（'+Math.round(node.width)+'×'+Math.round(node.height)+'px），符合单选/复选框特征' };
}

function(node){
  if (!node.width || !node.height) return null;
  if (node.width < 20 || node.width > 80) return null;
  var diff = Math.abs(node.width - node.height);
  if (diff > 4) return null;
  if (!node.cornerRadius || node.cornerRadius < node.width/2 - 4) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  if (node.width <= 24 && node.height <= 24) return null;
  return { confidence: 78, reason: '圆形头像占位（'+Math.round(node.width)+'×'+Math.round(node.height)+'px）' };
}

