function(node){
  var hasFill = (node.fills||[]).some(function(f){return f.type==='SOLID';});
  if (!hasFill) return null;
  var effects = node.effects || [];
  var hasShadow = effects.some(function(e){return e.type==='DROP_SHADOW'||e.type==='INNER_SHADOW';});
  if (!hasShadow) return null;
  var texts = node.textChildren || [];
  if (texts.length < 1) return null;
  var childTypes = node.childTypes || [];
  if (childTypes.includes('INSTANCE')) return null;
  if (!node.height || node.height > 200) return null;
  if (!node.width || node.width > 320) return null;
  return { confidence: 72, reason: '有背景+投影+文字，符合气泡/Toast特征' };
}

